DATASETS=['ground-truth','parakeet-automatic','parakeet-oracle_identity','whisper-automatic','whisper-oracle_identity']
DN={'ground-truth':'Ground truth','parakeet-automatic':'Parakeet · automatic speakers','parakeet-oracle_identity':'Parakeet · annotation-mapped speakers','whisper-automatic':'Whisper · automatic speakers','whisper-oracle_identity':'Whisper · annotation-mapped speakers'}
