CONDS=list(CN)[:3]
CSS='''
.results{max-width:1160px;margin:auto}.results section{padding:24px 0;border-top:1px solid var(--border);scroll-margin-top:10rem}.results .hero{padding:28px 0}.results h1{font-size:clamp(30px,4vw,46px)}.results h2{font-size:1.65rem}.results h3{margin-top:1.3rem}.results p,.results li{line-height:1.65}.results .findings li{margin:.65rem 0}.results .jump-links{display:flex;flex-wrap:wrap;gap:.5rem 1.3rem}.results audio{display:block;width:100%;max-width:620px;margin:.7rem 0}.results details{border:1px solid var(--border);padding:1rem;margin:1rem 0;border-radius:8px;min-width:0}.results summary{cursor:pointer;font-weight:650}.results .table-wrap{overflow-x:auto;margin:1rem 0}.results table{border-collapse:collapse;width:100%;font-size:.94rem}.results th,.results td{padding:.6rem .75rem;border-bottom:1px solid var(--border);text-align:left;vertical-align:top}.results th{white-space:nowrap}.results caption{text-align:left;font-weight:650;margin-bottom:.7rem}.results .native,.results pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--bg-soft,var(--surface));border-left:3px solid var(--border);padding:1rem;font-family:inherit;line-height:1.55;max-height:340px;overflow-y:auto}.results pre.prompt{font-family:ui-monospace,monospace;font-size:.83rem}.results .model-card{padding:1rem 0;border-top:1px solid var(--border)}.results .small{font-size:.9rem;color:var(--muted)}.results figure{margin:1.5rem 0}.results figure img{display:block;width:100%;height:auto;background:white;border-radius:5px}.results figcaption{font-size:.93rem;line-height:1.5;margin:.7rem 0}.results .transcript{max-height:420px;overflow:auto}.results .transcript p{margin:.6rem 0}.results .badge{font-size:.85rem;font-weight:650;padding:.2rem .5rem;border:1px solid var(--border);border-radius:5px}.results label{display:inline-block;margin:.5rem 1rem .5rem 0}.results select{max-width:100%;padding:.45rem;color:var(--text);background:var(--bg);border:1px solid var(--border)}.results .source{border-left:3px solid var(--accent);padding-left:1rem}.results .cost-table td{white-space:nowrap}.results [hidden]{display:none!important}.results .quality-note{max-width:900px}.results .checklist{list-style:none;padding-left:0}.results .checklist li{margin:.6rem 0}.results .checklist input{margin-right:.6rem}@media(max-width:650px){.results section{padding:18px 0}.results details{padding:.75rem}.results .table-wrap{font-size:.86rem}.results .native{padding:.7rem}.results .hero{padding-top:20px}}
'''
CSS+='''.results label{max-width:100%;box-sizing:border-box}.results select{width:100%;min-width:0;box-sizing:border-box}.results .badge{display:inline-block;max-width:100%;white-space:normal;overflow-wrap:anywhere;box-sizing:border-box}@media(max-width:650px){.results label{display:block;margin-right:0}.results select{display:block;margin-top:.4rem}}'''
JS='''
function reveal(){const id=decodeURIComponent(location.hash.slice(1));const target=document.getElementById(id);if(!target)return;for(let p=target;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;requestAnimationFrame(()=>target.scrollIntoView());}
addEventListener('hashchange',reveal);addEventListener('load',reveal);
function filterAnswers(){const ds=document.getElementById('answer-dataset').value;const model=document.getElementById('answer-model').value;const cond=document.getElementById('answer-condition').value;let count=0;document.querySelectorAll('.answer-row').forEach(x=>{const show=x.dataset.dataset===ds&&x.dataset.model===model&&(cond==='all'||x.dataset.condition===cond);x.hidden=!show;if(show)count++;});document.getElementById('answer-count').textContent=count+' saved answers shown';}
document.querySelectorAll('.answer-filter').forEach(x=>x.addEventListener('change',filterAnswers));filterAnswers();
document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause();})));
'''
def link(url,label):return '<a href="'+e(url,quote=True)+'">'+e(label)+'</a>'
def asset(url):return '../'+url
def audio(url,label):return '<audio controls preload="none" aria-label="'+e(label,quote=True)+'" src="'+e(asset(url),quote=True)+'"></audio>'
def text(s):return '<div class="native">'+e(s)+'</div>'
def details(title,body,id=None,opened=False):return '<details'+(' id="'+id+'"' if id else '')+(' open' if opened else '')+'><summary>'+e(title)+'</summary>'+body+'</details>'
def table(number,title,headers,rows,cls=''):
    return '<div class="table-wrap '+cls+'"><table><caption>Table '+str(number)+'. '+e(title)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def figure(number,name,caption):
    return '<figure id="fig-'+name+'"><a href="../research/answering-report/figures/'+name+'.svg"><img loading="lazy" src="../research/answering-report/figures/'+name+'.svg" alt="'+e(caption,quote=True)+'"></a><figcaption><strong>Figure '+str(number)+'.</strong> '+e(caption)+' '+link('../research/answering-report/figures/'+name+'.pdf','PDF')+' · '+link('../research/answering-report/figures/'+name+'.svg','SVG')+'</figcaption></figure>'
def transcript(rows):
    return '<div class="transcript">'+''.join('<p><strong>'+f"{s['start']:.2f}–{s['end']:.2f} s · "+e(s['speaker'])+'</strong> '+e(s['text'])+(' <span class="small">[sentence overlaps the crop boundary]</span>' if s.get('partial') else '')+'</p>' for s in rows)+'</div>'
def output_card(o,label):
    body='<article class="model-card"><h4>'+e(o['model'])+'</h4>'
    if not o.get('complete_input',True):
        body+='<p>'+e(o['failure'])+'</p>'+audio(o['actual_processed_audio'],label+' actual processed prefix')+text(o['native_text'] or '[No native answer]')
        if o.get('actual_processed_transcript'):body+=details('Transcript of the actually processed final 30 s',transcript(o['actual_processed_transcript']))
    else:
        status='Source-complete answer' if o['correct'] is True else 'Incomplete or unsupported answer' if o['correct'] is False else 'History lacks part of the answer evidence'
        body+='<p><span class="badge">'+status+'</span></p>'
        body+=audio(o.get('preview_audio',o.get('response_audio')),label+' · '+o['model']+' · input then response')+text(o['native_text'] or '[Empty native response]')
        if o.get('response_audio'):body+='<p class="small">'+link(asset(o['response_audio']),'Response audio separately')+'</p>'
        if o.get('criterion'):body+='<p class="small">'+e(o['criterion'])+'</p>'
    return body+'</article>'

def main():
    d=json.loads((P/'results.json').read_text());quality=json.loads((P/'quality.json').read_text()) if (P/'quality.json').exists() else None
    title='History-based answering: S1 and text S2 results'
    body='<header class="hero"><p class="small">Draft for review · 2 November 2026 · Development study</p><h1>'+title+'</h1></header>'
    body+='<section id="findings"><h2>Main findings</h2><ul class="findings">'
    findings=[
      ('S1 accuracy depends on the question: MiniCPM retrieves the seven-minute limit from full history, while all three models miss the shared-folder answer.','#s1-results'),
      ('DuplexOmni often emits no request transcript with longer history, and the folder sweep shows no consistent answer-failure threshold.','#s1-time'),
      ('With ground-truth transcripts, structured notes preserve six correct Thinking-model answers and reduce request-time thinking by 20%.','#s2-tradeoff'),
      ('Earlier notes sometimes help and sometimes introduce stale facts; the effect changes with the transcript and the note format.','#s2-cases'),
      ('Automatic transcripts have about 32–33% word error across these prefixes, yet answer accuracy also depends on retaining the particular facts the question needs.','#s2-asr'),
      ('Earlier thinking increases total generated tokens substantially, even when it reduces thinking after the request.','#s2-cost')]
    body+=''.join('<li>'+e(s)+' '+link(url,'Evidence and examples')+'</li>' for s,url in findings)+'</ul><p class="small">S1 is the duplex speech model; text S2 is the reasoning reader. Six distinct questions from five AMI meetings support this comparison; the question bank contains 105 source-reviewed questions.</p></section>'
    body+='<nav class="jump-links" aria-label="Results sections">'+''.join(link('#'+id,label) for id,label in [('s1-setup','S1 setup'),('s1-results','S1 outputs'),('s1-time','Time ablation'),('quality','Quality evaluation'),('s2-setup','S2 settings'),('s2-tradeoff','Accuracy and thinking'),('s2-cost','Token cost'),('appendix','Prompts and data'),('next','Next steps')])+'</nav>'
    body+='<section id="s1-setup"><h2>1. S1: audio history and native responses</h2><p>Each speech model receives meeting audio up to an inserted participant question beginning with “Assistant”. The input contains overlapping speech, pauses and the participant’s synthesized question in a matched voice. The original meeting pauses after the question. The model produces its native text and speech streams; correctness is assessed from the native text. Reference answers and source transcripts are supplied to the evaluator.</p>'
    body+='<p>The paired pilot has 13 inputs per model: six questions with supporting speech, the same six questions with full preceding history, and one short human-recorded control. Supporting-speech inputs concatenate the annotated evidence passages in chronological order, with small margins and packet-alignment padding; full-history inputs retain the continuous prefix. Both versions use the same question waveform. Query times range from 302.37 to 471.33 s.</p>'
    body+=table(1,'S1 execution and output capture.', ['System','Native audio step','Listening and response generation','Output and decoding'],[
      ['DuplexOmni','480 ms','Constrained listening retains the ASR and response-field history; answering is enabled at the known end of the question.','Native tts text and synthesized speech; greedy decoding, up to 256 tokens per call.'],
      ['Moshi','80 ms','Native generation and caches run throughout the input, including earlier response packets.','Native text stream and Mimi speech; released sampling settings: audio temperature 0.8, text temperature 0.7.'],
      ['MiniCPM-o 4.5','1 s','Native streaming prefill and generation run throughout the input; prior state is retained.','Native generated text and speech; greedy decoding.']])
    body+='<p>All audio is processed in sequence through the native model loop. This offline study measures answer content as a function of available history. The paired pilot appends 60 s of silence for responses; the matched time-ablation uses a 19.2 s response allowance. Moshi uses its native 3,000-frame attention window (about 240 s), which limits direct access to older audio even when the full prefix is processed. Model-specific internal context limits and prompts remain part of each system: MiniCPM and DuplexOmni receive a meeting-assistant instruction, while Moshi uses its native conditioning interface.</p>'
    body+='<p class="small">Audio examples below are sequential listening edits: selected input, a 0.6 s gap, then captured model speech. Outer quiet margins of the response are trimmed for listening, preserving all intervening speech. Native response text is shown verbatim; it may differ from the audible words. Sentence transcripts retain the original annotation text when a sentence crosses a crop boundary.</p></section>'
    body+='<section id="s1-results"><h2>2. S1 paired-question results</h2>'
    rows=[]
    for model in ['DuplexOmni','Moshi','MiniCPM']:
        rr=[]
        for variant in ['support','full']:
            oo=[o for c in d['pilot'] if c['variant']==variant for o in c['outputs'] if o['model']==model]
            rr.append(str(sum(o['correct'] is True for o in oo))+'/6'+(' (one input-processing failure)' if any(not o['complete_input'] for o in oo) else ''))
        rows.append([model,*rr,'Correct retail definition' if model!='Moshi' else 'Electrical-outlet answer'])
    body+=table(2,'Complete native-text answers among six scheduled questions in each history condition; the control is separate.', ['System','Supporting speech','Full history','Short control'],rows)
    body+='<p>MiniCPM answers the presentation-time question correctly with both inputs and recovers the lack-of-time reason for dropping audio work from the full prefix. DuplexOmni also mentions seven minutes with supporting speech, then asks for confirmation. Moshi gives a source-consistent explanation for abandoning the audio work with supporting speech. The remaining responses include greetings, offers to check, unsupported self-assignment of tasks, settled answers to unresolved choices, and unrelated continuations. DuplexOmni’s full-history slogan case stops before the question because of repeated input-ASR generation.</p>'
    body+='<p>These results suggest several distinct limitations: retaining an earlier quantity, identifying the person who made a commitment, tracking whether a decision was settled, and maintaining the role of a separate meeting assistant. The note-taking commitment occurs about 261 s before its request, placing it beyond Moshi’s direct attention window in that full-history case. The six-question sample also shows that removing intervening speech can change a response without consistently improving it.</p>'
    for qnum,q in enumerate(d['questions'],1):
        group=[c for c in d['pilot'] if c['question_id']==q['id']]
        content='<p><strong>Question:</strong> '+e(q['question'])+'</p><p><strong>Reference answer:</strong> '+e(q['reference_answer'])+'</p><p class="small">'+e(q['meeting'])+f" · original question time {q['at']:.2f} s</p>"
        for c in group:
            sub='<p>Earlier audio: '+f"{c['source_cutoff_seconds']:.2f} s"+'. '+('The player presents the final 30 s of the input, including the question.' if c['variant']=='full' else 'The player presents the entire supporting-speech input.')+'</p>'+audio(c['input_audio'],c['id']+' input')+details('Input transcript with edited-input times',transcript(c['transcript']))
            sub+=''.join(output_card(o,c['id']) for o in c['outputs'])
            content+=details(c['id']+' · '+('full history' if c['variant']=='full' else 'supporting speech'),sub,id='pilot-'+c['id'])
        body+=details(str(qnum)+'. '+q['question'],content,id='question-'+str(qnum))
    control=d['control'];ct='<p><strong>Human question:</strong> '+e(control['question'])+'</p>'+audio(control['input_audio'],'Short control input')
    for o in control['outputs']:ct+='<h4>'+e(o['model'])+'</h4>'+audio(o['response_audio'],'Control response '+o['model'])+text(o['native_text'])
    body+=details('13th input: short retail-outlet control',ct,id='native-control')
    full=next(c for c in d['pilot'] if c['id']=='M04-full')
    body+='<article id="full-history-example"><h3>Full-history listening example: presentation time</h3><p>This input includes 302.37 s of meeting history, followed by the question. The allowance appears around 145–163 s in the source. MiniCPM answers “Seven minutes”; DuplexOmni greets the user and Moshi gives general advice about time limits.</p>'+audio(full['full_preview_audio'],'Whole M04 input then MiniCPM response')+'<p>'+link(asset(full['full_input_audio']),'Whole original input separately')+' · '+link(asset(next(o['response_audio'] for o in full['outputs'] if o['model']=='MiniCPM')),'Complete captured MiniCPM response separately')+'</p>'+details('Full input transcript and all three native outputs',transcript(full['full_transcript'])+''.join('<h4>'+e(o['model'])+'</h4>'+text(o['native_text']) for o in full['outputs']))+'</article></section>'
    body+='<section id="s1-time"><h2>3. S1 time-ablation study</h2><p>The shared-folder question is held fixed while earlier audio is added backwards, one group of complete sentences at a time. Overlapping sentences are merged before boundary selection. The 41 input lengths span request-only through 309.03 s of earlier discussion. Each suffix is continuous and retains its original silence and overlap. A partial first packet is zero-padded to keep the same global packet phase. The spoken question is unchanged across lengths within each microphone condition.</p><p>Three recording conditions cover the headset mixture, one distant microphone and a beamformed eight-microphone array. The 123 inputs are reused across systems. Moshi and MiniCPM complete all 123; DuplexOmni completes 120 and has three generation failures. Full answer evidence is available for 11 lengths per recording condition, giving 33 eligible responses per model; all three models have 0/33 source-complete answers. The shorter suffixes are assessed for responding appropriately to limited context.</p>'
    body+='<p>The complete curves show changing response content rather than a monotonic memory threshold. DuplexOmni commonly offers to inspect the folder; Moshi often continues a different conversational thread; MiniCPM frequently assigns file ownership or a live folder state without sufficient support. These patterns coexist with MiniCPM’s successful quantity retrieval in the paired pilot. A failed shared-folder answer at request-only is compatible with missing evidence; a grounded response there should state that the status cannot be established.</p>'
    body+=figure(1,'s1-question-wer','DuplexOmni input-ASR WER for the inserted question at each history length. The shaded region contains the full supporting discussion. Three failed runs are omitted; Moshi and MiniCPM do not expose a comparable input-ASR field.')
    body+='<p>Question WER counts substitutions, deletions and insertions relative to the inserted question, divided by its word count. Text is lowercased, punctuation is removed and internal apostrophes are retained. Across the 33 full-evidence inputs, DuplexOmni emits an empty request-ASR field in 29 cases: nine headset, nine distant-microphone and all 11 beamformed cases. Empty fields receive 100% WER through deletions; insertions can raise WER above 100%. Only one full-evidence input has question WER at or below 25%. These observations show that request transcription and recovery of earlier facts both contribute to the long-history failures.</p>'
    marks=[]
    for c in d['sweep_examples']:
        signal={'headset_mix':'headset mixture','distant_01':'distant microphone','beamformed_mdm8':'beamformed array'}[c['condition']]
        sub='<p>'+e(c['question'])+f"</p><p>Earlier audio: {c['history_seconds']:.2f} s; source interval {c['source_start_seconds']:.2f}–309.03 s.</p>"+audio(c['input_audio'],c['id']+' final input 30 seconds')+'<p>'+link(asset(c['full_input_audio']),'Whole selected input')+'</p>'+details('Input preview transcript',transcript(c['transcript']))+details('Full selected input transcript',transcript(c['full_transcript']))
        sub+=''.join(output_card(o,c['id']) for o in c['outputs'])
        marks.append(details(f"{c['history_seconds']:.2f} s · {signal}",sub,id='time-'+c['id']))
    body+=details('Representative lengths and microphone conditions: audio and native text',''.join(marks),id='time-examples')
    body+='<p class="small">Moshi and MiniCPM native text is captured from request onset through the response allowance, which can include a continuation begun during the question. The downloadable record also retains their post-question text. Captured speech is concatenated in generation order. The '+link('../research/answering-report/results.json','complete results data')+' contains every native response at all 123 inputs per model.</p></section>'
    body+='<section id="quality"><h2>4. Quality checks and scoring</h2><p>Source-based correctness requires the requested facts and no material unsupported claim. Optional reference details are accepted through their meaning. For example, seven minutes is sufficient for the presentation question; the shared-folder answer must distinguish a reported file placement from verified current access. Codex reviews the native text against the transcript and the required facts. A human review of these ratings remains a useful next step.</p>'
    body+='<p>The aspect-wise quality evaluator is Qwen3-30B-A3B-Instruct-2507. Separate prompts rate question relevance, factual support and answer adequacy on anchored 1–5 scales. The relevance call sees the question and candidate. A clause-classification call identifies factual assertions; the support call checks those assertions against the available source transcript. The adequacy call sees the question, available transcript, reference answer and support assessment. References are adjusted to the actual suffix, so missing context receives an appropriate insufficient-evidence reference.</p>'
    body+=table(3,'Quality dimensions and anchor examples.', ['Dimension','Low rating','Middle rating','High rating'],[
      ['Question relevance','1: greeting or unrelated content','3: relevant offer without an answer','5: focused answer, including a clear inability to determine it'],
      ['Factual support','1: central unsupported claim or invented completed action','3: mostly supported, with an overstatement','5: all material factual claims supported'],
      ['Answer adequacy','1: no useful answer, or a fabricated answer','3: useful but materially incomplete','5: complete answer appropriate to the available evidence']])
    body+='<p>Support is unscored when a response has no factual assertion, such as a greeting or an offer to check. Those responses still receive relevance and adequacy ratings. Empty responses receive relevance 1, adequacy 1 and unscored support. Thirteen synthetic checks cover correct answers, paraphrases, offers, fabricated actions, contradictions, instruction text and empty output before ratings are applied to the saved model responses.</p>'
    if quality:
        body+=figure(2,'s1-quality','Native-text quality across history lengths, averaging the three recording conditions at each length. Factual support averages only scored responses; the number contributing can therefore vary. The shaded region contains the full source evidence. Ratings describe these nested contexts for one question.')
        body+=table(4,'Mean quality on the 33 time-ablation inputs with full evidence, by system.', ['System','Relevance','Factual support','Support scored','Adequacy'],quality['eligible_summary'])
        body+='<p>'+e(quality.get('analysis',''))+'</p><p class="small">'+e(quality['qualification_note'])+' '+link('../research/answering-report/quality.json','All ratings, feedback and checks')+' · '+link('../research/answering-report/quality-inputs.json','All evaluation inputs and source contexts')+' · '+link('../research/answering-report/quality-prompts.json','Exact evaluation messages')+'</p>'
        audit=''
        for r in quality['actual_response_audit']:
            audit+='<h4>'+e(r['case_id'])+'</h4>'+text(r['candidate'])+'<p>Automated ratings: '+e(json.dumps(r['scores']))+'.</p><p>'+e(r['source_audit'])+'</p>'
        body+=details('Actual examples: where the quality evaluator agrees and disagrees with source review',audit,id='quality-real-checks')
    else:body+='<p>The native-text quality evaluation is running; its ratings will be integrated after validation.</p>'
    body+=details('How scorer disagreements are interpreted','<p>An earlier binary-judge calibration agreed with Codex on 55 of 68 answers (80.9%); 11 disagreements accepted an answer Codex considered incomplete, and two went in the opposite direction. The report uses source review for correctness. These disagreements identify claims and criteria that need inspection.</p><p>For example, one answer gives the correct rule against capitalizing a continuing sentence, then incorrectly recommends a hyphen for continuation. The binary judge accepts it; source review flags the extra rule because the later discussion reserves the hyphen for a sentence that is definitely separate. In another case, the judge rejects an accepted backlighting answer because it demands an additional distinction between interior lighting and buttons. This second example calls for review of the reference criteria as well as the judge.</p><p>'+link('../research/comparison-followup/scorer-disagreements.json','Source passages and disagreement records')+'</p>',id='scorer-disagreements')
    body+='</section>'
    body+='<section id="s2-setup"><h2>5. Text S2: inputs, earlier thinking and answers</h2><p>Both readers are Qwen3-30B-A3B models: Instruct-2507 and Thinking-2507. Each answers the same six questions using the full available speaker-attributed transcript. Three main conditions compare reasoning only at the request with two forms of earlier, amortized thinking.</p>'
    body+=table(5,'Text S2 conditions; each condition has six request-time answers per reader and transcript input.', ['Condition','Before the request','At the request'],[
      ['Reactive','No model-generated notes.','Full transcript, requester label and question.'],
      ['Summary','After each selected boundary, update a summary of up to 180 words, retaining quantities, qualifications and source IDs.','Full transcript, all valid earlier summaries, requester label and question.'],
      ['Structured notes','Maintain speaker, fact or commitment, status (proposed/agreed/superseded/observed), source IDs and unresolved points.','Full transcript, all valid earlier structured notes, requester label and question.'],
      ['Selected-source control','No earlier thinking; annotations select relevant passages.','Only the selected transcript passages, requester label and question.']])
    body+='<p>The chunk schedule uses the requested 10–40 s range; these meetings yield 25–40 s chunks. Sentence and speaker-turn boundaries are preferred, and sparse chunks are merged or skipped for note generation. Across five meetings there are 55 chunks and 52 queried boundaries per thinking goal. Each note-generation call receives the observed transcript prefix and earlier valid results. The future user question is absent. At the request, the reader retains the full transcript alongside the valid notes. Invalid JSON or unavailable source citations exclude a note from reuse, while its generation cost remains counted.</p><p>Five transcript inputs are compared: ground-truth AMI transcripts; Parakeet or Whisper transcripts with automatic speaker labels; and the same generated transcripts with speaker clusters mapped to AMI labels using past annotations. The mapped condition keeps the recognized words, times and boundaries fixed. The question itself is supplied as text in every S2 condition; generated ASR covers the preceding meeting audio. Query text and chunk boundaries are held constant across these comparisons.</p>'
    body+='<p>Inference uses vLLM in BF16 with CUDA graphs, prefix caching and a 65,536-token context limit. Instruct uses greedy decoding and a 2,048-token output cap. Thinking uses temperature 0.6 and top-p 0.95, with caps of 8,192 tokens for earlier calls and 16,384 at the request. Each setting has one sampled run. All 240 request outputs across the five inputs, two readers and four conditions contain complete final JSON; 79 of the 832 generated-transcript earlier calls and 21 of the 208 ground-truth earlier calls fail reuse checks.</p></section>'
    body+='<section id="s2-asr"><h2>6. Generated-transcript quality</h2><p>Parakeet-TDT-0.6B-v2 and Whisper-large-v3 transcribe the same observed audio prefixes. Sortformer 4-speaker v2.1 supplies speaker activity. Parakeet supplies word times; Whisper words are aligned with a CTC model, using recognized words as the alignment text. Word times assign words to speaker activity and enforce the observed-prefix cutoff. Whisper uses predicted speech regions, 0.3 s padding, temperature fallback and repetition checks. This alignment step uses no ground-truth words.</p>'
    body+=figure(3,'s2-transcript-wer','Generated histories compared with the ground-truth prefix at each question. Lexical WER serializes segments by time. Speaker-attributed cpWER concatenates each speaker’s words and finds the speaker-label permutation with minimum total word errors.')
    body+='<p>Across the six evaluated prefixes, word-weighted lexical WER is 32.9% for Parakeet and 32.5% for Whisper; speaker-attributed cpWER is 37.8% and 37.4%, respectively. The two EN2002b prefixes overlap in source time, so these aggregates weight the audio as used by the six evaluation cases. WER retains fillers and numbers as written after case and punctuation normalization. The '+link('https://github.com/fgnt/meeteval/blob/main/doc/algorithms.md','MeetEval definition')+' guides the cpWER calculation; speaker-label permutations include unmatched clusters as empty streams.</p>'
    body+='<p>Recognition and speaker attribution contribute differently. For the presentation-time case, Parakeet’s lexical WER is 18.0%, while cpWER is 40.4%, indicating substantial additional speaker-attribution or within-speaker sequence error. Both pipelines have approximately 42–43% lexical WER on the audio-work prefix, yet their Thinking readers can still recover a recorded reason for abandoning that work. Conversely, the outreach case can retain the relevant timing words while the answer uses an older deadline. These examples motivate checking task evidence alongside aggregate WER.</p><p class="small">The diarization model’s training data include AMI. These runs characterize the current prototype on the selected development meetings.</p></section>'
    body+='<section id="s2-tradeoff"><h2>7. Answer accuracy and request-time thinking</h2>'
    body+=figure(4,'s2-accuracy','Source-complete answers out of six questions for each reader, transcript input and main condition. Speaker-label mapping changes identities only. The selected-source control is listed separately in the detailed table.')
    body+=figure(5,'s2-request-thinking','Mean request-time native thinking tokens for Qwen3-30B Thinking over all six questions, including incorrect answers. Earlier thinking and final answer tokens are excluded. Instruct has no exposed native thinking channel.')
    body+='<p>With ground-truth transcripts, the Thinking reader answers 6/6 questions in both reactive and structured-note conditions. Structured notes lower mean request-time thinking from 2,278 to 1,815 tokens (20.3%). Summaries lower it to 2,042 tokens but reduce correctness to 4/6. Instruct improves from 4/6 to 5/6 with structured notes. Parakeet with automatic speaker labels shows the same correctness pattern, with a smaller 4.5% thinking reduction for structured notes.</p><p>The Whisper automatic-speaker condition provides a favorable paired result: summaries increase Thinking accuracy from 4/6 to 5/6 while lowering request-time thinking from 1,933 to 1,459 tokens (24.5%). Structured notes also reach 5/6 with 1,895 tokens. With annotation-mapped Whisper speakers, structured notes improve accuracy from 4/6 to 5/6 while increasing thinking from 1,740 to 1,847 tokens (6.1%). Earlier thinking therefore offers a setting-dependent trade-off between answer quality and request-time reasoning.</p><p>Paired answer changes are concentrated in a few facts. Ground-truth and Parakeet automatic-speaker summaries lose the revised outreach deadline and folder-access qualification in the Thinking reader. Structured notes recover the folder answer for Instruct with ground-truth and both Parakeet speaker conditions. With Whisper transcripts, Instruct’s note-based gains occur on the unresolved slogan choice, while Thinking’s automatic-speaker gains occur on the revised outreach deadline.</p><p>Speaker-label mapping has no consistent advantage in these runs. For example, the Parakeet Thinking reactive condition changes from 6/6 to 4/6 after identity mapping, despite identical recognized words and times. Prompt sensitivity and stochastic decoding can contribute to this change; repeated paired runs are needed to estimate its stability.</p>'
    rows=[]
    for ds in DATASETS:
        for model in ['instruct','thinking']:
            rr=[next(r for r in d['s2_summary'] if r['dataset']==ds and r['model']==model and r['condition']==c) for c in CONDS]
            rows.append([e(DN[ds]),model.capitalize(),*[str(r['correct'])+'/6'+(f" · {r['mean_request_thinking']:,.0f} thinking tokens" if r['mean_request_thinking'] is not None else '') for r in rr],str(next(r['correct'] for r in d['s2_summary'] if r['dataset']==ds and r['model']==model and r['condition']=='source_excerpt_diagnostic'))+'/6'])
    body+=details('Exact accuracy and mean thinking-token values',table(6,'Correct answers and request-time native thinking; each cell averages six questions.', ['Transcript input','Reader','Reactive','Summary','Structured notes','Selected-source control'],rows))+'</section>'
    body+='<section id="s2-cost"><h2>8. Total token cost</h2><p>Request-time thinking tokens are the Thinking model’s native reasoning tokens generated after the user asks. Earlier thinking tokens are generated by the question-blind note calls. Ordinary output tokens contain saved notes or final answers; delimiters are counted separately. Instruct’s native thinking count is unexposed, and its ordinary output count is reported directly.</p>'
    body+=figure(6,'s2-total-tokens','Total generated tokens across the six questions, including earlier thinking, saved-note text, request-time thinking, final answer text and delimiters. The logarithmic axis keeps reactive and amortized conditions visible. Each meeting’s earlier calls are counted once per goal, including rejected notes.')
    body+='<p>For the ground-truth Thinking reader, reactive answering generates 14,254 tokens across six questions. Structured notes generate 306,014 earlier tokens plus 11,482 request-time tokens, totaling 317,496 (22.3× reactive). Summaries total 237,272 (16.6× reactive). Whisper automatic-speaker summaries provide the favorable accuracy/think-at-request result above while increasing generated tokens from 12,249 to 219,623 (17.9×). These measurements show that the current schedule moves useful work earlier at a substantial total token cost.</p><p>The total charges all 52 earlier calls for each goal once across the five meetings, including invalid results; the two questions in EN2002b share that meeting’s earlier work. Input-token counts are reported separately because the full transcript and accumulated notes are repeatedly supplied. Prefix-cache hits and hardware work saved by caching were not recorded, so token counts are used as a reproducible cost proxy.</p>'
    costrows=[]
    for r in d['s2_summary']:
        if r['condition']=='source_excerpt_diagnostic':continue
        costrows.append([e(DN[r['dataset']]),r['model'].capitalize(),CN[r['condition']],f"{r['earlier_generated']:,}",f"{r['request_thinking']:,}" if r['request_thinking'] is not None else 'Unexposed',f"{r['request_output']:,}",f"{r['total_generated']:,}",f"{r['earlier_input']+r['request_input']:,}"])
    body+=details('Exact stage costs and input-token totals',table(7,'Token totals across six request answers and one shared earlier pass per meeting/goal.', ['Transcript','Reader','Condition','Earlier generated','Request thinking','Request ordinary output','All generated','All input tokens'],costrows,'cost-table')+'<p>'+link('../research/answering-report/token-costs.json','Download all stage counts, including delimiter tokens')+'</p>')+'</section>'
    body+='<section id="s2-cases"><h2>9. Qualitative comparison: preserving a revised deadline</h2><p>The outreach question asks who will send the main call, when it will be sent, and why Claire will send a separate Psychology call. The earlier “end of week” plan is later revised to “today or tomorrow”. This case tests task ownership, revision tracking and the rationale distributed across speakers.</p>'
    for ds,explanation in [('ground-truth','The summary retains the older end-of-week deadline; the final answer combines it with today or tomorrow. Structured notes preserve the later commitment and produce a complete answer.'),('whisper-automatic','The reactive answer uses the older end-of-week deadline. Both note formats retain the revised timing and produce complete answers with fewer request-time thinking tokens on this case.')]:
        body+='<h3>'+e(DN[ds])+' · Thinking reader</h3><p>'+e(explanation)+'</p>'
        for cond in CONDS:
            r=next(a for a in d['s2_answers'] if a['dataset']==ds and a['model']=='thinking' and a['condition']==cond and a['question_id']=='first:authored-W1-2')
            body+='<h4>'+CN[cond]+f" · {'complete' if r['complete'] else 'incomplete'} · {r['native_thinking_tokens']:,} request-time thinking tokens</h4>"+text(r['answer'])
            valid=[n for n in r['notes'] if not n['validation_errors']]
            if valid:body+=details('Latest saved notes actually supplied',text(json.dumps(valid[-1]['artifact']['result'],ensure_ascii=False,indent=2)))
    body+='<p>Earlier notes can also turn an unresolved folder-access discussion into a settled state. The ground-truth Thinking reactive and structured-note answers retain the distinction between reported placement and unverified access; its summary condition loses the complete answer. The saved-note and answer records below permit comparison of the exact claims. Such cases favor explicit revision status and source timestamps as targets for the next note-generation design.</p>'
    body+='<h3 id="all-s2-answers">Inspect all S2 answers</h3><p>Choose transcript input and reader; each record includes the reference decision, response and token counts.</p><label>Transcript <select class="answer-filter" id="answer-dataset">'+''.join('<option value="'+ds+'">'+e(DN[ds])+'</option>' for ds in DATASETS)+'</select></label><label>Reader <select class="answer-filter" id="answer-model"><option value="thinking">Thinking</option><option value="instruct">Instruct</option></select></label><label>Condition <select class="answer-filter" id="answer-condition"><option value="all">All four conditions</option>'+''.join('<option value="'+c+'">'+label+'</option>' for c,label in CN.items())+'</select></label><p id="answer-count" aria-live="polite"></p>'
    for r in d['s2_answers']:
        q=next(q for q in d['questions'] if q['id']==r['question_id'])
        sub='<p><strong>Question:</strong> '+e(q['question'])+'</p><p><strong>Reference:</strong> '+e(q['reference_answer'])+'</p>'+text(r['answer'])+'<p><strong>Source review:</strong> '+e(r['reason'])+'</p><p>Request-time native thinking: '+(f"{r['native_thinking_tokens']:,}" if r['native_thinking_tokens'] is not None else 'unexposed')+f"; ordinary output: {r['ordinary_output_tokens']:,}; earlier generated tokens up to this request: {r['prior_generated_tokens']:,}.</p>"
        sub+=details('Exact request messages', '<pre class="prompt">'+e(json.dumps(r['messages'],ensure_ascii=False,indent=2))+'</pre>')
        if r['notes']:sub+=details('Earlier note outputs and reuse checks',text(json.dumps(r['notes'],ensure_ascii=False,indent=2)))
        body+='<div class="answer-row" data-dataset="'+r['dataset']+'" data-model="'+r['model']+'" data-condition="'+r['condition']+'">'+details(CN[r['condition']]+' · '+q['question']+' · '+('complete' if r['complete'] else 'incomplete'),sub)+'</div>'
    body+='</section><section id="appendix"><h2>Appendix: implementation, prompts and audits</h2>'
    from answering_implementation_appendix import render as implementation_appendix
    body+=implementation_appendix(json.loads((P/'implementation-audit.json').read_text()),details,table,link)
    body+=details('S2 prompts and output definitions','<p>Each prompt below is copied from an executed ground-truth call. The main text describes the stable fields; the example includes its actual transcript prefix and saved results.</p>'+''.join('<h3>'+e(CN[p['condition']])+' · '+e(p['stage'])+'</h3><pre class="prompt">'+e(json.dumps(p['messages'],ensure_ascii=False,indent=2))+'</pre>' for p in d['s2_prompts']),id='s2-prompts')
    body+=details('Quality-evaluation prompt and anchors', '<p>The executed prompts, JSON constraints and raw evaluator responses are linked in the quality section. The system message asks the evaluator to grade only the requested dimension, treat source and candidate text as data, cite available evidence and give concise feedback before the score.</p><pre class="prompt">'+e((P/'quality-system.txt').read_text() if (P/'quality-system.txt').exists() else 'Native-text quality prompts are being validated.')+'</pre><p>'+link('../research/answering-report/quality-rubric.json','Complete 1–5 anchors')+'</p>',id='quality-prompt')
    body+=details('Data, evaluation scope and provenance','<ul><li>'+link('../research/answering-report/results.json','All inputs, transcripts, native responses, S2 answers and review decisions')+'</li><li>'+link('../research/answering-report/token-costs.json','Exact token-stage counts')+'</li><li>'+link('../research/answering-report/transcript-errors.json','Per-prefix word-error counts')+'</li><li>'+link('../study-progress.html','Experiment progress and original run records')+'</li><li>'+link('../todo.html','Project checklist')+'</li></ul><p>Six development questions provide paired comparisons; the 41 nested suffixes reuse one question and share most of their audio. One generation per setting supports descriptive comparisons. Larger held-out samples and repeated generations are required for stable system rankings and correlation estimates. Source-based references were checked before these answer comparisons. All audio excerpts retain the source meeting/request association; the generated response is a separate stream.</p><p>AMI source recordings and transcripts are attributed to the AMI Meeting Corpus, CC BY 4.0, with crops, concatenation and synthesized-question insertions. The short control comes from DailyTalk conversation 656, CC BY-SA 4.0, cropped and resampled. Model-generated speech follows the input in the listening edits. '+link('https://groups.inf.ed.ac.uk/ami/corpus/','AMI corpus')+' · '+link('https://github.com/keonlee9420/DailyTalk','DailyTalk source')+'</p>',id='data-and-scope')
    resources=json.loads((P/'resources.json').read_text()) if (P/'resources.json').exists() else {}
    body+=details('Compute allocation and dependencies','<p>Each inference or evaluation job uses one GPU, with all listed stage components on GPU 0. S1 codec/speech components share the native-model GPU; generated-transcript and text-reader jobs run as separate stages. The new quality evaluation uses one H100 SXM 80 GB for judge weights and KV cache, without an S1 or ASR service. Figure generation, audio editing, HTML rendering and validation use zero GPUs.</p><pre>'+e(json.dumps(resources,ensure_ascii=False,indent=2))+'</pre>',id='resources')
    body+='</section><section id="next"><h2>Next steps and goals</h2><ul class="checklist"><li><input type="checkbox" checked disabled>Audit native outputs, source references and token accounting for this report.</li><li><input type="checkbox" checked disabled>Publish audio examples, exact prompts and source-linked judgments for review.</li><li><input type="checkbox" disabled>Review disputed answers and ordinal ratings with human readers to strengthen evaluation reliability.</li><li><input type="checkbox" disabled>Separate request-transcription failures from retrieval errors to diagnose S1 behavior with longer histories.</li><li><input type="checkbox" disabled>Repeat paired S2 runs on held-out meetings to test whether the accuracy and thinking-token gains persist.</li><li><input type="checkbox" disabled>Reduce and revise earlier notes to retain current commitments with less total token cost.</li></ul></section>'
    page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="S1 history ablations, native response audio, generated-transcript WER and text S2 accuracy versus thinking-token cost."><title>'+title+' · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css"><style>'+CSS+'</style></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><div class="container collection-nav">'+experiment_subtabs('answering')+'</div><main id="main" class="container results">'+body+'</main><script>'+JS+'</script></body></html>\n'
    css_version=hashlib.sha256((ROOT/'assets/site.css').read_bytes()).hexdigest()[:12]
    page=page.replace('href="../assets/site.css"','href="../assets/site.css?v='+css_version+'"')
    (ROOT/'experiments/answering-results.html').write_text(page)
    manifest={str(p.relative_to(P)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(P.rglob('*')) if p.is_file() and p.name!='manifest.json'}
    (P/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print('Built answering-results.html with 13 paired/control inputs and all 240 S2 answers.')
